CREATE TABLE [dbo].[ccGenChart](	  [chartId] INT NOT NULL IDENTITY(1,1)	, [show] BIT NOT NULL DEFAULT(1)	, [chartInfo] VARCHAR(50) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [chartTitle] VARCHAR(50) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [axisX] VARCHAR(50) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [axisY] VARCHAR(50) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [defaultChart] TINYINT NOT NULL DEFAULT(0)	, [chartGroup] VARCHAR(50) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [query] VARCHAR(1500) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [filter] VARCHAR(200) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, CONSTRAINT [PK_ccGenChart] PRIMARY KEY ([chartId] ASC))